/* ============================================================================
   SITUATIONAL POOLS — v3
   ----------------------------------------------------------------------------
   The thirteen "<Axis> — Situational" categories are the most-drawn-from part of
   the entire bank and were the thinnest: twelve or thirteen entries each, with
   nothing at all above intensity 3. They serve the whole ±14 neutral band PLUS a
   weighted share of the 14–42 blend — which is to say, every character generated
   at or near default slider positions draws thirteen traits from thirteen pools
   of twelve. That, not the trait count, was the largest single cause of "everything
   I generate feels the same": the engine was fine, it just kept being handed the
   same dozen cards.

   These bring each pool to 40+, and — importantly — they extend it upward. A
   situational trait is not a WEAK trait: "warm one-to-one, unrecognisable in a
   group" can be the single most defining fact about a person. Intensity here means
   how pronounced the conditionality is, not how loud the behaviour is, so this set
   runs the full 1–5 range where the old one stopped at 3.

   ids start at 110000.
   ========================================================================== */
const TRAITS_SITUATIONAL = [

/* ---------- Friendliness — Situational ---------- */
{id:110001,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warmer by daylight",desc:"Noticeably friendlier in the morning than after dark, without ever remarking on it.",example:"Morning! — (at nine that evening) ...yeah.",intensity:1,rarity:"common",pol:{}},
{id:110002,section:"Personality Traits",category:"Friendliness — Situational",trait:"Friendly until asked a favour",desc:"Perfectly warm right up to the moment the conversation acquires a purpose.",example:"Lovely to see you. — What is it you actually want?",intensity:2,rarity:"common",pol:{}},
{id:110003,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warm to strangers, guarded with the familiar",desc:"Gives more of themselves to people who won't be around next week.",example:"You'll be gone Thursday. Easier to talk to you.",intensity:3,rarity:"distinctive",pol:{}},
{id:110004,section:"Personality Traits",category:"Friendliness — Situational",trait:"Kind in a crisis, indifferent otherwise",desc:"Appears fully, generously present only when something has gone badly wrong.",example:"You're bleeding. Sit. — (a week later) Do I know you?",intensity:3,rarity:"distinctive",pol:{}},
{id:110005,section:"Personality Traits",category:"Friendliness — Situational",trait:"One-to-one warm, invisible in a group",desc:"Genuinely engaged with one person; contributes nothing at all once there are four.",example:"(talks for an hour over the sink; says nine words at the table)",intensity:4,rarity:"signature",pol:{}},
{id:110006,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warmth strictly by shift",desc:"Reliably good company at work and entirely unreachable outside it.",example:"See you Monday. — (does not answer the phone on Sunday)",intensity:3,rarity:"uncommon",pol:{}},
{id:110007,section:"Personality Traits",category:"Friendliness — Situational",trait:"Softer around anyone smaller",desc:"Curt with adults, immediately gentle with children and animals.",example:"Move. — (kneeling) Hello. What've you got there?",intensity:2,rarity:"uncommon",pol:{}},
{id:110008,section:"Personality Traits",category:"Friendliness — Situational",trait:"Cools by degrees over an evening",desc:"Arrives warm and withdraws steadily as the night goes on, every time.",example:"(hour one: laughing. hour four: coat already on.)",intensity:2,rarity:"common",pol:{}},
{id:110009,section:"Personality Traits",category:"Friendliness — Situational",trait:"Friendly to the point of the transaction",desc:"Warmth is real and switches off cleanly the moment business concludes.",example:"Pleasure. Truly. — (already turning away)",intensity:2,rarity:"common",pol:{}},
{id:110010,section:"Personality Traits",category:"Friendliness — Situational",trait:"Only warm where they're the host",desc:"Generous and open in their own space, stiff and formal in anyone else's.",example:"Sit anywhere, eat anything. — (at yours) I'm fine standing.",intensity:3,rarity:"distinctive",pol:{}},
{id:110011,section:"Personality Traits",category:"Friendliness — Situational",trait:"Distant with anyone who might stay",desc:"Warm to passers-through, careful with anyone who looks likely to become permanent.",example:"You're moving here? Ah. (the register changes)",intensity:4,rarity:"signature",pol:{}},
{id:110012,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warmth follows competence",desc:"Friendly exactly in proportion to how good someone turns out to be at their job.",example:"You know what you're doing. Come and sit with us.",intensity:3,rarity:"uncommon",pol:{}},
{id:110013,section:"Personality Traits",category:"Friendliness — Situational",trait:"Different person on the phone",desc:"Markedly warmer, or markedly colder, on a call than in the same conversation in person.",example:"(bright and chatty down the line; silent across the table)",intensity:2,rarity:"common",pol:{}},
{id:110014,section:"Personality Traits",category:"Friendliness — Situational",trait:"Thaws after the second drink, reliably",desc:"A fixed and well-observed threshold at which they become good company.",example:"(everyone waits for it; it always arrives)",intensity:2,rarity:"common",pol:{}},
{id:110015,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warm in writing, remote in person",desc:"Letters and messages read as affectionate; the same person face-to-face is barely there.",example:"(three warm paragraphs; then a nod in the corridor)",intensity:3,rarity:"distinctive",pol:{}},
{id:110016,section:"Personality Traits",category:"Friendliness — Situational",trait:"Their whole manner tracks one other person",desc:"Warmth is entirely a function of whether a specific individual is in the room.",example:"(you can tell she's arrived without turning around)",intensity:5,rarity:"signature",pol:{}},
{id:110017,section:"Personality Traits",category:"Friendliness — Situational",trait:"Polite to all, close to nobody in particular",desc:"Even, pleasant, and undifferentiated — nobody gets more than anybody else.",example:"Good to see you. (says it identically, to everyone, for years)",intensity:2,rarity:"common",pol:{}},
{id:110018,section:"Personality Traits",category:"Friendliness — Situational",trait:"Only rude when tired",desc:"Consistently decent except at the end of a long day, when it drops away entirely.",example:"Sorry. I'm not — it's late. I'll be better tomorrow.",intensity:1,rarity:"common",pol:{}},
{id:110019,section:"Personality Traits",category:"Friendliness — Situational",trait:"Cold to the new, loyal to the old",desc:"Every relationship is glacial for a year and then unconditional.",example:"I don't know you yet. Ask me in a year.",intensity:3,rarity:"distinctive",pol:{}},
{id:110020,section:"Personality Traits",category:"Friendliness — Situational",trait:"Friendliness scales with distance from home",desc:"Expansive and easy while travelling, closed and short once back in familiar streets.",example:"(the best company in the world, four hundred miles away)",intensity:3,rarity:"distinctive",pol:{}},
{id:110021,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warm to those below, brisk to those above",desc:"Considerably kinder to anyone with less standing than to anyone with more.",example:"(twenty minutes with the porter; ninety seconds with the director)",intensity:3,rarity:"distinctive",pol:{}},
{id:110022,section:"Personality Traits",category:"Friendliness — Situational",trait:"Only unguarded outdoors",desc:"Conversation opens up on a walk and closes the moment there are walls and chairs.",example:"Let's not do this sitting down. Come on, get your coat.",intensity:4,rarity:"signature",pol:{}},
{id:110023,section:"Personality Traits",category:"Friendliness — Situational",trait:"Cordial in public, blunt in private",desc:"Two settings, cleanly separated by whether anyone else is listening.",example:"Of course, delighted. — (door closes) Absolutely not.",intensity:3,rarity:"uncommon",pol:{}},
{id:110024,section:"Personality Traits",category:"Friendliness — Situational",trait:"Friendliness is entirely weather-dependent",desc:"Sociability rises and falls with the sky, consistently enough to plan around.",example:"(the first warm day, and suddenly they're on everyone's doorstep)",intensity:2,rarity:"common",pol:{}},
{id:110025,section:"Personality Traits",category:"Friendliness — Situational",trait:"Loses all warmth around a certain topic",desc:"Excellent company until one specific subject comes up, and then completely unreachable.",example:"— no. Not that. Ask me something else.",intensity:4,rarity:"signature",pol:{}},
{id:110026,section:"Personality Traits",category:"Friendliness — Situational",trait:"Kinder to people they've decided are doomed",desc:"Reserves real gentleness for whoever they've privately concluded is not going to make it.",example:"(sits with him every evening. Doesn't say why.)",intensity:5,rarity:"signature",pol:{}},
{id:110027,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warmth resets after any absence",desc:"However close you were, a few weeks apart returns them to formal politeness.",example:"(back to surnames after a fortnight)",intensity:3,rarity:"distinctive",pol:{}},
{id:110028,section:"Personality Traits",category:"Friendliness — Situational",trait:"Notably warmer when there's work to do",desc:"Companionable and easy while occupied; awkward and remote with nothing in their hands.",example:"Pass me that. — (job finished; conversation dies)",intensity:2,rarity:"common",pol:{}},

/* ---------- Honesty — Situational ---------- */
{id:110029,section:"Personality Traits",category:"Honesty — Situational",trait:"Truthful about facts, evasive about feelings",desc:"Scrupulously accurate on anything checkable and unreachable on anything internal.",example:"Two hours, forty minutes, one stop. — How was it? It was two hours forty.",intensity:3,rarity:"distinctive",pol:{}},
{id:110030,section:"Personality Traits",category:"Honesty — Situational",trait:"Lies only to protect somebody else",desc:"Entirely straight about themselves, freely dishonest on another's behalf.",example:"He was with me all evening. (he was not)",intensity:3,rarity:"distinctive",pol:{}},
{id:110031,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest in writing, slippery out loud",desc:"Will not put a falsehood on paper; says whatever the room requires.",example:"I'm not writing that down. Saying it's fine.",intensity:3,rarity:"distinctive",pol:{}},
{id:110032,section:"Personality Traits",category:"Honesty — Situational",trait:"Straight in business, loose in anecdote",desc:"Rigorous where it counts, cheerfully improving any story where it doesn't.",example:"The invoice is exact. The fish was enormous.",intensity:2,rarity:"common",pol:{}},
{id:110033,section:"Personality Traits",category:"Honesty — Situational",trait:"Won't lie, will let you believe it",desc:"Never states a falsehood and never corrects a convenient misunderstanding either.",example:"(said nothing at all, and let the room draw its conclusion)",intensity:3,rarity:"distinctive",pol:{}},
{id:110034,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest until embarrassed",desc:"Truthful by default, with a reflexive small lie any time they're caught out.",example:"I did — no. I didn't. Sorry. I don't know why I said that.",intensity:2,rarity:"common",pol:{}},
{id:110035,section:"Personality Traits",category:"Honesty — Situational",trait:"Absolute honesty inside one relationship",desc:"Habitually shades the truth with everyone except one person, with whom they can't.",example:"You I can't lie to. It's very inconvenient.",intensity:4,rarity:"signature",pol:{}},
{id:110036,section:"Personality Traits",category:"Honesty — Situational",trait:"Exact about numbers, vague about intentions",desc:"Precise on quantities and dates; fog descends the moment it's about what they meant to do.",example:"Six, on the fourteenth. What I was planning is — complicated.",intensity:2,rarity:"common",pol:{}},
{id:110037,section:"Personality Traits",category:"Honesty — Situational",trait:"Confesses everything eventually",desc:"Lies comfortably in the moment and always tells the truth about it later, unprompted.",example:"That thing I said last week. It wasn't true. I've been carrying it.",intensity:3,rarity:"distinctive",pol:{}},
{id:110038,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest only when it costs them",desc:"Volunteers the truth precisely when it hurts, and shades it when it wouldn't matter.",example:"It was my fault. — (about the small stuff) Who knows. Could've been anyone.",intensity:4,rarity:"signature",pol:{}},
{id:110039,section:"Personality Traits",category:"Honesty — Situational",trait:"One standing lie, otherwise transparent",desc:"Wholly candid about their entire life apart from a single, permanent fiction.",example:"Ask me anything. (there is exactly one thing you must not ask)",intensity:5,rarity:"signature",pol:{}},
{id:110040,section:"Personality Traits",category:"Honesty — Situational",trait:"Truth depends on who's in the room",desc:"The account changes with the audience, and they keep every version straight.",example:"(three tellings, three shapes, no contradiction anyone can prove)",intensity:4,rarity:"signature",pol:{}},
{id:110041,section:"Personality Traits",category:"Honesty — Situational",trait:"Softens bad news, never the facts",desc:"Delivers everything accurately and buries the sharp edge under wording.",example:"It's not the outcome we wanted. — Say it plainly. — He died.",intensity:2,rarity:"common",pol:{}},
{id:110042,section:"Personality Traits",category:"Honesty — Situational",trait:"Blunt about themselves, careful about others",desc:"Merciless in self-description and diplomatic to the point of unhelpfulness about anyone else.",example:"I was useless. He was... he had a difficult year.",intensity:2,rarity:"common",pol:{}},
{id:110043,section:"Personality Traits",category:"Honesty — Situational",trait:"Deceives by omission only",desc:"Every sentence is true; the shape of what's left out does all the work.",example:"I was in the building. (for six hours. with him.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110044,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest when sober, expansive when not",desc:"A dependable narrator until the third drink, after which the story improves.",example:"— and there were forty of them. — There were four. — Forty.",intensity:2,rarity:"common",pol:{}},
{id:110045,section:"Personality Traits",category:"Honesty — Situational",trait:"Won't lie under oath, will everywhere else",desc:"Treats formal settings as binding and everything outside them as negotiable.",example:"In there I'd have to tell you. Out here? Out here we're just talking.",intensity:3,rarity:"distinctive",pol:{}},
{id:110046,section:"Personality Traits",category:"Honesty — Situational",trait:"Truthful in the language they grew up in",desc:"Harder to lie, and visibly so, in their first language than in any other.",example:"(switches tongue and the story simplifies)",intensity:4,rarity:"signature",pol:{}},
{id:110047,section:"Personality Traits",category:"Honesty — Situational",trait:"Small lies to smooth, large truths to shock",desc:"Constant social fictions, punctuated by the occasional devastating candour.",example:"Lovely, lovely. — Actually, no, I've hated it here for eleven years.",intensity:3,rarity:"uncommon",pol:{}},
{id:110048,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest about the past, evasive about the plan",desc:"Complete disclosure of anything already done; nothing at all about what's next.",example:"I'll tell you everything I did. What I'm doing is mine.",intensity:3,rarity:"distinctive",pol:{}},
{id:110049,section:"Personality Traits",category:"Honesty — Situational",trait:"Cannot lie to a direct question",desc:"Evades freely until someone asks outright, at which point the truth arrives whole.",example:"...yes. You asked. So, yes.",intensity:4,rarity:"signature",pol:{}},
{id:110050,section:"Personality Traits",category:"Honesty — Situational",trait:"Rounds in their own favour, once",desc:"A single consistent, minor exaggeration that never grows and never goes away.",example:"Nearly six foot. (for thirty years, at five ten)",intensity:1,rarity:"common",pol:{}},
{id:110051,section:"Personality Traits",category:"Honesty — Situational",trait:"Truthfulness collapses under praise",desc:"Reliable until flattered, at which point they'll agree to almost anything.",example:"Well — yes. Yes, I suppose I did do that.",intensity:2,rarity:"common",pol:{}},
{id:110052,section:"Personality Traits",category:"Honesty — Situational",trait:"Only honest on the way out of a room",desc:"Says the true thing at the door, where the conversation can't continue.",example:"(hand on the handle) It was never about the money. Night.",intensity:3,rarity:"distinctive",pol:{}},
{id:110053,section:"Personality Traits",category:"Honesty — Situational",trait:"Never lies twice about the same thing",desc:"Will shade a fact once, then hold to whatever they said, correcting later if pressed.",example:"I've already told you what I'm going to tell you.",intensity:2,rarity:"common",pol:{}},
{id:110054,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest with the dying, careful with the living",desc:"Withholds nothing from someone who has run out of time, and manages everyone else.",example:"You want it straight? Right. Here it is, all of it.",intensity:5,rarity:"signature",pol:{}},
{id:110055,section:"Personality Traits",category:"Honesty — Situational",trait:"Answers the question underneath",desc:"Ignores what was literally asked and answers the thing they judge you actually meant.",example:"You're asking whether I'd do it again. Yes.",intensity:2,rarity:"common",pol:{}},
{id:110056,section:"Personality Traits",category:"Honesty — Situational",trait:"Discloses under time pressure only",desc:"Says nothing for months, then tells you everything with four minutes left.",example:"Right — quickly, before you go, there's something —",intensity:3,rarity:"distinctive",pol:{}},

/* ---------- Assertiveness — Situational ---------- */
{id:110057,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Decisive on the small, paralysed on the large",desc:"Instant on lunch and logistics, unable to settle anything that matters.",example:"Left, second door, twenty past. — About the move? I don't know. I don't know.",intensity:3,rarity:"distinctive",pol:{}},
{id:110058,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Takes charge only when nobody else will",desc:"Content to follow indefinitely, and steps forward the moment the vacuum appears.",example:"(twelve seconds of silence) Fine. Me, then. Here's what we're doing.",intensity:3,rarity:"distinctive",pol:{}},
{id:110059,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Forceful in their own field, deferential outside it",desc:"Immovable on their specialism and instantly compliant on everything else.",example:"On the engine, no. On where we eat, whatever you like.",intensity:3,rarity:"uncommon",pol:{}},
{id:110060,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Speaks up for others, never themselves",desc:"Will fight a room on someone else's behalf and accept anything on their own.",example:"She asked first. — (about their own claim) It's fine, honestly.",intensity:4,rarity:"signature",pol:{}},
{id:110061,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Assertive in writing, yielding in person",desc:"Sends a firm, unambiguous message and folds within a minute of the meeting starting.",example:"(the email said 'unacceptable'; the room heard 'if that works for everyone')",intensity:3,rarity:"distinctive",pol:{}},
{id:110062,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Pushes hard early, concedes late",desc:"Opens any negotiation immovably and gives everything back in the last five minutes.",example:"Absolutely not. — (an hour later) All right, fine, yes.",intensity:2,rarity:"common",pol:{}},
{id:110063,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Only firm with strangers",desc:"Will hold a hard line with anyone they don't know and none at all with anyone they do.",example:"(unmovable at the counter; agrees to everything at home)",intensity:3,rarity:"distinctive",pol:{}},
{id:110064,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Command voice only in an emergency",desc:"Quiet and easily talked over until something is actually on fire.",example:"(three words, and the whole room does what it's told)",intensity:4,rarity:"signature",pol:{}},
{id:110065,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Defers to age, ignores rank",desc:"Automatically yields to anyone older and entirely unimpressed by title.",example:"Yes, sir — (to the seventy-year-old porter, not the director)",intensity:3,rarity:"distinctive",pol:{}},
{id:110066,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Holds ground on process, folds on content",desc:"Fights hard about how a decision gets made and shrugs at what it turns out to be.",example:"We vote. I don't care what it says, but we vote.",intensity:3,rarity:"distinctive",pol:{}},
{id:110067,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Assertive until contradicted once",desc:"Comes in strong and abandons the position at the first sign of real resistance.",example:"I'm certain — well. You may be right. Forget it.",intensity:2,rarity:"common",pol:{}},
{id:110068,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Runs the room, then vanishes from it",desc:"Directs decisively for the length of the task and disappears the second it's done.",example:"(gone before anyone can ask a follow-up question)",intensity:2,rarity:"common",pol:{}},
{id:110069,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Says no in advance, yes in the moment",desc:"Refuses everything at the planning stage and agrees to all of it on the day.",example:"I'm not going. — (is there, first)",intensity:2,rarity:"common",pol:{}},
{id:110070,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Immovable about one thing, easy about everything",desc:"Universally accommodating with a single non-negotiable that nobody sees coming.",example:"Whatever you like. Whatever you like. — Not that. Never that.",intensity:5,rarity:"signature",pol:{}},
{id:110071,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Direct up close, indirect at distance",desc:"Says it to your face and hints at it through three intermediaries otherwise.",example:"(a rumour reaches you first; then, later, the sentence itself)",intensity:3,rarity:"uncommon",pol:{}},
{id:110072,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Only pushes when representing someone",desc:"Toothless on their own account and formidable the moment they hold a mandate.",example:"I'm not asking for me. I'm asking for the ward.",intensity:4,rarity:"signature",pol:{}},
{id:110073,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Firm at the start of the day only",desc:"Everything decided before noon holds; anything after it can be renegotiated.",example:"Ask me at eight. Don't ask me at four.",intensity:2,rarity:"common",pol:{}},
{id:110074,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Assertive with equals, silent with either extreme",desc:"Perfectly able among peers, mute with anyone much senior or much junior.",example:"(fluent in the meeting; nothing at all in the corridor)",intensity:3,rarity:"distinctive",pol:{}},
{id:110075,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Objects only after agreeing",desc:"Signs on immediately and raises every problem afterwards, at length.",example:"Yes, fine. — (twenty minutes later) Although.",intensity:2,rarity:"common",pol:{}},
{id:110076,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Will not lead but will veto",desc:"Never proposes anything and reliably kills any proposal they dislike.",example:"I've no better idea. I just know it isn't that one.",intensity:3,rarity:"distinctive",pol:{}},
{id:110077,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Takes the floor only when angry",desc:"Contributes nothing until provoked, then speaks fluently and at length.",example:"(hasn't said a word all evening; now can't be interrupted)",intensity:3,rarity:"uncommon",pol:{}},
{id:110078,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Louder in a language they speak badly",desc:"More forceful, not less, when working in an unfamiliar tongue.",example:"(fewer words available, so every one of them lands harder)",intensity:2,rarity:"uncommon",pol:{}},
{id:110079,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Deference is a tactic, not a temperament",desc:"Yields conspicuously in public and gets exactly what they wanted afterwards.",example:"Of course, you're quite right. (the outcome is unchanged)",intensity:4,rarity:"signature",pol:{}},
{id:110080,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Assertive precisely to the edge of politeness",desc:"Pushes as hard as decorum permits and stops dead at the line, every time.",example:"I'd press this further if we were somewhere else.",intensity:2,rarity:"common",pol:{}},
{id:110081,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Cannot start a conversation, cannot end one",desc:"Needs someone else to open and someone else to close, but holds the middle well.",example:"(waits to be spoken to; then talks until the other person leaves)",intensity:3,rarity:"distinctive",pol:{}},
{id:110082,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Forceful in the second attempt only",desc:"Asks once, mildly and easily refused; asks the second time in a way that ends it.",example:"I did ask nicely. That was the nice one.",intensity:3,rarity:"distinctive",pol:{}},
{id:110083,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Insists on their own terms, never their own share",desc:"Fights over conditions and takes whatever's left when it comes to the split.",example:"My way, and you can have the bigger half.",intensity:4,rarity:"signature",pol:{}},
{id:110084,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Only definite about what they won't do",desc:"Vague on every plan and completely unambiguous about their refusals.",example:"I don't know what we're doing. I know it isn't that.",intensity:1,rarity:"common",pol:{}},

/* ---------- Confidence — Situational ---------- */
{id:110085,section:"Personality Traits",category:"Confidence — Situational",trait:"Steady in a crisis, anxious about trivia",desc:"Unshakeable when it's serious; visibly rattled by small domestic decisions.",example:"(calm through the fire; forty minutes over which shirt)",intensity:3,rarity:"distinctive",pol:{}},
{id:110086,section:"Personality Traits",category:"Confidence — Situational",trait:"Certain until asked to explain",desc:"Complete conviction that dissolves the moment someone requests the reasoning.",example:"I'm sure. — Why? — ...I was sure a second ago.",intensity:2,rarity:"common",pol:{}},
{id:110087,section:"Personality Traits",category:"Confidence — Situational",trait:"Confident in the doing, doubtful in the retelling",desc:"Never hesitates at the time and picks the whole thing apart afterwards.",example:"(flawless on the night; awake at three re-running it)",intensity:3,rarity:"distinctive",pol:{}},
{id:110088,section:"Personality Traits",category:"Confidence — Situational",trait:"Assured with tools, uncertain with people",desc:"Total competence with objects and a complete loss of footing in conversation.",example:"(rebuilds it blind; can't manage 'how was your weekend')",intensity:3,rarity:"distinctive",pol:{}},
{id:110089,section:"Personality Traits",category:"Confidence — Situational",trait:"Self-belief lasts exactly one setback",desc:"Fully assured until the first thing goes wrong, then entirely rebuilt from scratch.",example:"One bad meeting and we're back to first principles.",intensity:2,rarity:"common",pol:{}},
{id:110090,section:"Personality Traits",category:"Confidence — Situational",trait:"Confident on paper, hesitant aloud",desc:"Writes with total authority and can't hold the same position in a room.",example:"(the report is unambiguous; the author is not)",intensity:3,rarity:"uncommon",pol:{}},
{id:110091,section:"Personality Traits",category:"Confidence — Situational",trait:"Assured only where they can be checked",desc:"Bold about anything verifiable and evasive about anything a matter of judgement.",example:"Look it up. — And your opinion? — I'd rather not.",intensity:3,rarity:"distinctive",pol:{}},
{id:110092,section:"Personality Traits",category:"Confidence — Situational",trait:"Grows into a room over an hour",desc:"Arrives diminished and is running the conversation by the end of it, predictably.",example:"(barely audible at seven; unmissable by nine)",intensity:2,rarity:"common",pol:{}},
{id:110093,section:"Personality Traits",category:"Confidence — Situational",trait:"Confidence tracks whether they've eaten",desc:"Self-assurance is a straightforward function of blood sugar and sleep.",example:"Don't ask me anything until after lunch.",intensity:1,rarity:"common",pol:{}},
{id:110094,section:"Personality Traits",category:"Confidence — Situational",trait:"Sure of the work, unsure of their place in it",desc:"No doubt at all about the thing they made and constant doubt about deserving to.",example:"It's good. I don't know why they let me do it.",intensity:4,rarity:"signature",pol:{}},
{id:110095,section:"Personality Traits",category:"Confidence — Situational",trait:"Bold in the second language, timid in the first",desc:"Freer and more forward where the words come with less history attached.",example:"(a different, braver person for the length of the conversation)",intensity:3,rarity:"distinctive",pol:{}},
{id:110096,section:"Personality Traits",category:"Confidence — Situational",trait:"Certainty scales inversely with stakes",desc:"Absolutely assured about trivia and visibly unsteady on anything with weight.",example:"(definitive on the crossword; hedging on the diagnosis)",intensity:3,rarity:"distinctive",pol:{}},
{id:110097,section:"Personality Traits",category:"Confidence — Situational",trait:"Falters only in front of one person",desc:"Composed with everyone in the world except a single specific individual.",example:"(fluent all day; loses the thread the moment he walks in)",intensity:4,rarity:"signature",pol:{}},
{id:110098,section:"Personality Traits",category:"Confidence — Situational",trait:"Confident in company, doubtful alone",desc:"Entirely convincing in front of people and dismantled by their own kitchen at midnight.",example:"(brilliant at the table; awful at 2am, same day)",intensity:3,rarity:"uncommon",pol:{}},
{id:110099,section:"Personality Traits",category:"Confidence — Situational",trait:"Assured about the past, uncertain about the present",desc:"Total clarity on what they used to be and no view at all on what they are now.",example:"I know exactly who I was. Ask me about now and I've nothing.",intensity:4,rarity:"signature",pol:{}},
{id:110100,section:"Personality Traits",category:"Confidence — Situational",trait:"Loses confidence when praised, gains it when doubted",desc:"Compliments unsettle them; open scepticism makes them suddenly certain.",example:"You don't think I can? Watch.",intensity:3,rarity:"distinctive",pol:{}},
{id:110101,section:"Personality Traits",category:"Confidence — Situational",trait:"Steady until observed",desc:"Wholly capable right up to the moment someone is explicitly watching.",example:"(perfect in rehearsal; hands shaking on the night)",intensity:3,rarity:"uncommon",pol:{}},
{id:110102,section:"Personality Traits",category:"Confidence — Situational",trait:"Confidence is borrowed from the group",desc:"As sure as whoever they're standing next to, and no surer.",example:"(exactly as brave as the bravest person in the room)",intensity:3,rarity:"distinctive",pol:{}},
{id:110103,section:"Personality Traits",category:"Confidence — Situational",trait:"Assured in uniform, uncertain out of it",desc:"Fully inhabits a role and has no idea how to stand without one.",example:"(commands a ward at eight; hovers in a doorway at six)",intensity:4,rarity:"signature",pol:{}},
{id:110104,section:"Personality Traits",category:"Confidence — Situational",trait:"Believes in the plan, not in themselves",desc:"Complete faith in the method and none whatsoever in their ability to execute it.",example:"It'll work. Just — maybe not with me doing it.",intensity:3,rarity:"distinctive",pol:{}},
{id:110105,section:"Personality Traits",category:"Confidence — Situational",trait:"Nerve holds until the last step",desc:"Carries anything through to within sight of the finish and stalls there.",example:"(everything done except the one signature)",intensity:3,rarity:"distinctive",pol:{}},
{id:110106,section:"Personality Traits",category:"Confidence — Situational",trait:"Self-assurance rises with distance from home",desc:"Diffident where they're known and formidable where nobody has a prior opinion.",example:"(nobody here remembers who I was. It's marvellous.)",intensity:3,rarity:"uncommon",pol:{}},
{id:110107,section:"Personality Traits",category:"Confidence — Situational",trait:"Only unsure in front of the young",desc:"Perfectly assured with peers and quietly intimidated by anyone twenty years younger.",example:"(they'll know I'm faking it. They always know.)",intensity:2,rarity:"uncommon",pol:{}},
{id:110108,section:"Personality Traits",category:"Confidence — Situational",trait:"Doubt arrives only in writing",desc:"Says it with total conviction and hedges every clause the moment it's typed.",example:"(spoken: 'it's this.' written: 'it may possibly be this, though.')",intensity:2,rarity:"common",pol:{}},
{id:110109,section:"Personality Traits",category:"Confidence — Situational",trait:"Certain of the diagnosis, unsure of the treatment",desc:"Confident naming a problem and hesitant about what anyone should do next.",example:"I know exactly what's wrong. Don't ask me how to fix it.",intensity:2,rarity:"common",pol:{}},
{id:110110,section:"Personality Traits",category:"Confidence — Situational",trait:"Whole self-image rests on one skill",desc:"Unshakeable while doing the one thing they're good at; nothing anywhere else.",example:"(a different height entirely with the instrument in their hands)",intensity:5,rarity:"signature",pol:{}},
{id:110111,section:"Personality Traits",category:"Confidence — Situational",trait:"Braver by phone than in the room",desc:"Says the difficult thing readily down a line and never once face to face.",example:"(the call took ninety seconds. The visit never happened.)",intensity:2,rarity:"common",pol:{}},
{id:110112,section:"Personality Traits",category:"Confidence — Situational",trait:"Confident until someone agrees too readily",desc:"Immediate suspicion of any position that turns out to be easy to hold.",example:"You agree? Hm. Then I've probably got it wrong.",intensity:2,rarity:"uncommon",pol:{}},
/* ---------- Agreeableness — Situational ---------- */
{id:110113,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agrees in the room, does otherwise",desc:"Never contradicts anyone present and quietly proceeds exactly as they intended.",example:"Sounds good to me. (does not do it)",intensity:3,rarity:"distinctive",pol:{}},
{id:110114,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Accommodating on method, immovable on timing",desc:"Will do it any way you like, and not one day later than they said.",example:"However you want. Thursday.",intensity:2,rarity:"common",pol:{}},
{id:110115,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Argues with those they respect, agrees with those they don't",desc:"Real disagreement is a compliment; blank consent is dismissal.",example:"(fights her for an hour; nods at him and moves on)",intensity:4,rarity:"signature",pol:{}},
{id:110116,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Contrary only about small things",desc:"Concedes on anything consequential and digs in over the trivial.",example:"Sell the house, fine. We are not repainting that door.",intensity:2,rarity:"common",pol:{}},
{id:110117,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agreeable one-to-one, obstructive in committee",desc:"Entirely reasonable alone with anyone and impossible the moment there's a quorum.",example:"(said yes to all six of them separately; blocked it in the meeting)",intensity:4,rarity:"signature",pol:{}},
{id:110118,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Goes along until it's irreversible",desc:"Cooperative through every stage and objects at the exact point of no return.",example:"Now hold on. — We signed an hour ago. — Yes. Now hold on.",intensity:3,rarity:"distinctive",pol:{}},
{id:110119,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Yields on anything they didn't propose",desc:"Fights only for their own ideas and hands over the rest without a word.",example:"Not my plan. Do what you like with it.",intensity:2,rarity:"common",pol:{}},
{id:110120,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Difficult in the morning, pliable by evening",desc:"A reliable daily arc from obstruction to easy agreement.",example:"Ask him after five. Never before ten.",intensity:2,rarity:"common",pol:{}},
{id:110121,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Cooperative with strangers, contrary with family",desc:"Endlessly accommodating outside the house and reflexively oppositional inside it.",example:"(charm itself at the counter; ten minutes of no at the table)",intensity:3,rarity:"distinctive",pol:{}},
{id:110122,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Says yes and renegotiates later",desc:"Agreement is a way of ending the conversation, not a settled position.",example:"Yes. — (next week) About that. Slight adjustment.",intensity:2,rarity:"common",pol:{}},
{id:110123,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Only obliging where there's a witness",desc:"Cooperative in front of an audience and flatly uninterested without one.",example:"(helpful while anyone's watching; gone the instant they aren't)",intensity:3,rarity:"distinctive",pol:{}},
{id:110124,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Disagrees by asking questions",desc:"Never states an objection and dismantles the proposal one query at a time.",example:"No, no, it's a good plan. Just — how does the second part work?",intensity:3,rarity:"distinctive",pol:{}},
{id:110125,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Accommodating until the third request",desc:"Two favours cheerfully, and the third produces a wholly different person.",example:"Course. — Course. — No. And that's the end of it.",intensity:2,rarity:"common",pol:{}},
{id:110126,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Contrarian with authority, biddable with peers",desc:"Reflexively resists anyone with standing and defers easily to anyone without it.",example:"(no to the director; yes to whoever asked next)",intensity:3,rarity:"uncommon",pol:{}},
{id:110127,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agrees fastest with whoever spoke last",desc:"Genuinely persuaded by every position in turn, in order of arrival.",example:"That's a good point. — (five minutes later) No, THAT'S a good point.",intensity:2,rarity:"common",pol:{}},
{id:110128,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Difficult exactly once per relationship",desc:"Wholly easy to work with apart from a single, memorable, immovable refusal.",example:"(everyone who knows them can name the one time)",intensity:4,rarity:"signature",pol:{}},
{id:110129,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Cooperative on the day, resentful the week after",desc:"Full agreement in the moment followed by a slow, quiet accounting.",example:"No, it was fine. It was fine. — (it was not fine)",intensity:3,rarity:"distinctive",pol:{}},
{id:110130,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Concedes to tiredness, not to argument",desc:"Cannot be reasoned out of a position and can be outlasted every time.",example:"You haven't convinced me. I'm just too tired. Take it.",intensity:3,rarity:"distinctive",pol:{}},
{id:110131,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Obliging with money, immovable with time",desc:"Gives freely from the wallet and defends the diary like a border.",example:"Take what you need. Do not put it in my calendar.",intensity:3,rarity:"distinctive",pol:{}},
{id:110132,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agrees with the room, disagrees in the corridor",desc:"Consensus in the meeting, full opposition to two people afterwards.",example:"(unanimous inside; the real meeting happens by the lift)",intensity:3,rarity:"uncommon",pol:{}},
{id:110133,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Only argumentative about their own field",desc:"Serene about everything except the one subject they actually know.",example:"Whatever you think. — (on the one topic) That is simply wrong.",intensity:2,rarity:"common",pol:{}},
{id:110134,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agreeable in proportion to how recently they slept",desc:"An entirely predictable inverse relationship, obvious to everyone but them.",example:"He's had four hours. Nobody ask him anything.",intensity:1,rarity:"common",pol:{}},
{id:110135,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agrees with the plan, fights the person",desc:"No objection to the proposal and every objection to whoever brought it.",example:"It's the right call. I still don't want it coming from him.",intensity:3,rarity:"distinctive",pol:{}},
{id:110136,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Yields to anything framed as a favour",desc:"Immovable against a demand and defenceless against a request.",example:"No. — Please? — ...fine.",intensity:2,rarity:"common",pol:{}},
{id:110137,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Every position is negotiable except loyalty",desc:"Flexible on all questions of fact and unmovable on any question of sides.",example:"I'll grant you all of that. I'm still not leaving him.",intensity:5,rarity:"signature",pol:{}},
{id:110138,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Contrary only when outnumbered",desc:"Perfectly agreeable in a pair and reflexively opposed once it's four to one.",example:"(the only no in the room, again)",intensity:3,rarity:"distinctive",pol:{}},
{id:110139,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agrees loudly, complies slowly",desc:"Enthusiastic assent followed by an indefinite delay nobody can quite pin down.",example:"Absolutely — it's on my list. (it has been on the list since March)",intensity:2,rarity:"common",pol:{}},
{id:110140,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Reasonable until the subject is fairness",desc:"Flexible on everything except an unequal split, where they become immovable.",example:"I don't care about the money. I care that it's not even.",intensity:3,rarity:"distinctive",pol:{}},

/* ---------- Manners — Situational ---------- */
{id:110141,section:"Personality Traits",category:"Manners — Situational",trait:"Courtesy switches off at their own door",desc:"Impeccable manners in public and none at all with the people they live with.",example:"(three thank-yous at the shop; not one at the table)",intensity:3,rarity:"distinctive",pol:{}},
{id:110142,section:"Personality Traits",category:"Manners — Situational",trait:"Formal until first names are offered",desc:"Rigid courtesy that drops the instant permission is explicitly granted.",example:"Mr Aldridge. — Call me Tom. — Tom. Right. So anyway —",intensity:1,rarity:"common",pol:{}},
{id:110143,section:"Personality Traits",category:"Manners — Situational",trait:"Polite to staff, careless with peers",desc:"Scrupulous with anyone serving them and offhand with everyone at their own level.",example:"(thanks the waiter by name; interrupts his own colleague twice)",intensity:3,rarity:"distinctive",pol:{}},
{id:110144,section:"Personality Traits",category:"Manners — Situational",trait:"Manners appear when they want something",desc:"Ordinary courtesy is a reliable early warning of an approaching request.",example:"You look well. Really well. — What do you need?",intensity:2,rarity:"common",pol:{}},
{id:110145,section:"Personality Traits",category:"Manners — Situational",trait:"Table manners perfect, conversation crude",desc:"Faultless with cutlery and entirely unfiltered in what they say over it.",example:"(napkin folded correctly; the anecdote is unrepeatable)",intensity:3,rarity:"distinctive",pol:{}},
{id:110146,section:"Personality Traits",category:"Manners — Situational",trait:"Courteous in their own language only",desc:"All the softening particles live in the mother tongue; the second language comes out blunt.",example:"(warm and elaborate at home; five flat words at work)",intensity:3,rarity:"distinctive",pol:{}},
{id:110147,section:"Personality Traits",category:"Manners — Situational",trait:"Ceremonious with the old, casual with everyone else",desc:"Full formality for anyone above a certain age and none whatsoever below it.",example:"(a small bow for her; 'oi' for everyone under sixty)",intensity:2,rarity:"common",pol:{}},
{id:110148,section:"Personality Traits",category:"Manners — Situational",trait:"Politeness sharpens when angry",desc:"Courtesy becomes more elaborate, not less, in exact proportion to their fury.",example:"Would you be so very kind as to repeat that.",intensity:4,rarity:"signature",pol:{}},
{id:110149,section:"Personality Traits",category:"Manners — Situational",trait:"Impeccable at first meeting, sloppy by the third",desc:"Manners are an introduction, not a habit, and decay on a predictable schedule.",example:"(coat taken, chair pulled out — then, by March, feet on the desk)",intensity:2,rarity:"common",pol:{}},
{id:110150,section:"Personality Traits",category:"Manners — Situational",trait:"Observes every ritual they were taught, ignores the rest",desc:"Punctilious about a specific inherited set and indifferent to any other convention.",example:"Hat off indoors, always. Whether I interrupt you is between us.",intensity:3,rarity:"distinctive",pol:{}},
{id:110151,section:"Personality Traits",category:"Manners — Situational",trait:"Rude to anyone who is late",desc:"Otherwise courteous, with one specific and total exception.",example:"(warm to the whole table; will not look at the man who arrived at ten past)",intensity:2,rarity:"common",pol:{}},
{id:110152,section:"Personality Traits",category:"Manners — Situational",trait:"Formal in writing, coarse in speech",desc:"Correspondence could be framed; the same person out loud cannot be quoted.",example:"(letter: 'I remain, sincerely.' in person: unprintable)",intensity:3,rarity:"uncommon",pol:{}},
{id:110153,section:"Personality Traits",category:"Manners — Situational",trait:"Manners hold exactly as long as they're sober",desc:"Faultless courtesy with a hard, well-documented time limit.",example:"(there is an hour at which the room quietly braces)",intensity:3,rarity:"uncommon",pol:{}},
{id:110154,section:"Personality Traits",category:"Manners — Situational",trait:"Punctilious with enemies, easy with friends",desc:"Full formal apparatus for anyone they dislike; nothing at all for anyone they don't.",example:"(the more correct he is with you, the worse it's going)",intensity:4,rarity:"signature",pol:{}},
{id:110155,section:"Personality Traits",category:"Manners — Situational",trait:"Only polite where they're outnumbered",desc:"Courtesy is a function of the arithmetic of the room.",example:"(gracious among strangers; unbearable at home)",intensity:3,rarity:"distinctive",pol:{}},
{id:110156,section:"Personality Traits",category:"Manners — Situational",trait:"Apologises constantly, thanks never",desc:"An endless stream of sorries and no acknowledgement of anything given.",example:"Sorry — sorry — sorry. (takes the coffee without a word)",intensity:2,rarity:"common",pol:{}},
{id:110157,section:"Personality Traits",category:"Manners — Situational",trait:"Manners return in a hospital or a church",desc:"Ordinary bluntness that yields completely to certain institutional rooms.",example:"(a different vocabulary entirely, the moment they cross the threshold)",intensity:2,rarity:"common",pol:{}},
{id:110158,section:"Personality Traits",category:"Manners — Situational",trait:"Courteous to the point of coldness with anyone they've hurt",desc:"Guilt expresses itself as formality, never as warmth.",example:"(hasn't used her first name since it happened)",intensity:4,rarity:"signature",pol:{}},
{id:110159,section:"Personality Traits",category:"Manners — Situational",trait:"Adopts the manners of whoever they're with",desc:"Courtesy level is copied wholesale from the company, within minutes.",example:"(unrecognisable across two rooms in the same evening)",intensity:3,rarity:"distinctive",pol:{}},
{id:110160,section:"Personality Traits",category:"Manners — Situational",trait:"Ceremonial about food, careless about everything else",desc:"One domain of absolute observance surrounded by general indifference.",example:"Nobody eats until everyone sits. — (walks through your conversation)",intensity:3,rarity:"distinctive",pol:{}},
{id:110161,section:"Personality Traits",category:"Manners — Situational",trait:"Politeness is load-bearing and everyone knows it",desc:"So thoroughly mannered that any lapse reads as a major event.",example:"He didn't say good morning. Something's badly wrong.",intensity:5,rarity:"signature",pol:{}},
{id:110162,section:"Personality Traits",category:"Manners — Situational",trait:"Rude only about things, never people",desc:"Scathing about work, weather, and objects; never once about a person present.",example:"That is the worst chair ever built. You're lovely. The chair is a crime.",intensity:2,rarity:"common",pol:{}},
{id:110163,section:"Personality Traits",category:"Manners — Situational",trait:"Says please to machines and not to people",desc:"Courtesy directed reliably at anything that can't hear it.",example:"(thanks the door; ignores whoever held it)",intensity:2,rarity:"uncommon",pol:{}},
{id:110164,section:"Personality Traits",category:"Manners — Situational",trait:"Manners are entirely for the audience",desc:"Immaculate whenever observed and instantly abandoned when not.",example:"(holds the door until the last witness turns the corner)",intensity:3,rarity:"uncommon",pol:{}},
{id:110165,section:"Personality Traits",category:"Manners — Situational",trait:"Formality increases with bad news",desc:"The worse the message, the more elaborate the language carrying it.",example:"I regret that I must inform you — (it's very bad)",intensity:3,rarity:"distinctive",pol:{}},
{id:110166,section:"Personality Traits",category:"Manners — Situational",trait:"Courteous everywhere except behind a wheel",desc:"One specific context in which the manners vanish completely and immediately.",example:"(a genuinely different man, from the moment the engine starts)",intensity:2,rarity:"common",pol:{}},
{id:110167,section:"Personality Traits",category:"Manners — Situational",trait:"Never interrupts, never yields the floor",desc:"Scrupulous about waiting their turn and impossible to get back from once it's theirs.",example:"(perfect manners; forty uninterrupted minutes)",intensity:3,rarity:"distinctive",pol:{}},
{id:110168,section:"Personality Traits",category:"Manners — Situational",trait:"Politeness thins with each repetition",desc:"The first ask is gracious, the second neutral, the third bare.",example:"Would you mind — Could you — Move.",intensity:2,rarity:"common",pol:{}},
/* ---------- Discipline — Situational ---------- */
{id:110169,section:"Personality Traits",category:"Discipline — Situational",trait:"Systems at the bench, none at the sink",desc:"Every professional process documented and enforced; the domestic half of their life has no method at all.",example:"(the workshop log goes back nine years. There is no shopping list, ever.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110170,section:"Personality Traits",category:"Discipline — Situational",trait:"Disciplined only against a deadline",desc:"Entirely unproductive until a date exists, then relentless.",example:"Give me a date and I'm a machine. Don't and I'm nothing.",intensity:3,rarity:"uncommon",pol:{}},
{id:110171,section:"Personality Traits",category:"Discipline — Situational",trait:"Keeps other people's rules, not their own",desc:"Never misses an obligation to someone else and abandons every private commitment.",example:"(never late for you; hasn't run in four months as promised)",intensity:3,rarity:"distinctive",pol:{}},
{id:110172,section:"Personality Traits",category:"Discipline — Situational",trait:"Order in one room only",desc:"A single perfectly kept space in the middle of general disarray.",example:"(the desk is surgical. Everything within six feet of it is not.)",intensity:2,rarity:"common",pol:{}},
{id:110173,section:"Personality Traits",category:"Discipline — Situational",trait:"Self-control holds until unobserved",desc:"Exemplary while anyone might notice, and immediately abandoned alone.",example:"(a saint at the table; the fridge tells another story)",intensity:2,rarity:"common",pol:{}},
{id:110174,section:"Personality Traits",category:"Discipline — Situational",trait:"Disciplined in crisis, undisciplined in peace",desc:"Immaculate under pressure and completely unstructured the moment it lifts.",example:"(six flawless weeks; then nothing for three months)",intensity:3,rarity:"distinctive",pol:{}},
{id:110175,section:"Personality Traits",category:"Discipline — Situational",trait:"Follows a system only until it works",desc:"Rigorous adherence right up to the point of success, then abandons it entirely.",example:"It fixed the problem, so I stopped doing it. Yes, I know.",intensity:3,rarity:"distinctive",pol:{}},
{id:110176,section:"Personality Traits",category:"Discipline — Situational",trait:"Punctual for people, late for institutions",desc:"Never keeps a person waiting and reliably misses anything with a building attached.",example:"(early for you; missed the appointment for the third time)",intensity:2,rarity:"common",pol:{}},
{id:110177,section:"Personality Traits",category:"Discipline — Situational",trait:"Meticulous about the tools, careless about the work",desc:"Everything cleaned, sharpened and put away; the job itself half-finished.",example:"(the bench is perfect. Nothing on it is done.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110178,section:"Personality Traits",category:"Discipline — Situational",trait:"Restraint applies to one appetite only",desc:"Iron control in a single domain and none at all in every other.",example:"Not a drop in eleven years. (four packs a day)",intensity:3,rarity:"distinctive",pol:{}},
{id:110179,section:"Personality Traits",category:"Discipline — Situational",trait:"Routine survives everything except travel",desc:"An unbreakable daily structure that dissolves completely away from home.",example:"(same hour, same order, every day — and utter chaos in a hotel)",intensity:2,rarity:"common",pol:{}},
{id:110180,section:"Personality Traits",category:"Discipline — Situational",trait:"Disciplined for others, indulgent for themselves",desc:"Enforces standards rigorously and exempts themselves without noticing.",example:"Nobody eats at the desk. (eats at the desk)",intensity:3,rarity:"uncommon",pol:{}},
{id:110181,section:"Personality Traits",category:"Discipline — Situational",trait:"Order arrives with anxiety",desc:"Tidies, sorts and files in exact proportion to how badly things are going.",example:"He's alphabetising the shelves. It must be worse than we thought.",intensity:3,rarity:"distinctive",pol:{}},
{id:110182,section:"Personality Traits",category:"Discipline — Situational",trait:"Rigid about mornings, formless after dark",desc:"The first four hours are structured to the minute and the rest is unplanned.",example:"(five to six is sacred. Nine onward is anybody's guess.)",intensity:2,rarity:"common",pol:{}},
{id:110183,section:"Personality Traits",category:"Discipline — Situational",trait:"Finishes what's started publicly",desc:"Every announced commitment completed; every private one quietly dropped.",example:"If I've told you I'll do it, it's done. If I haven't, it isn't.",intensity:3,rarity:"distinctive",pol:{}},
{id:110184,section:"Personality Traits",category:"Discipline — Situational",trait:"Self-denial in company, indulgence alone",desc:"Abstemious in front of anyone and entirely unrestrained in private.",example:"Nothing for me, thanks. (later, alone: everything)",intensity:3,rarity:"distinctive",pol:{}},
{id:110185,section:"Personality Traits",category:"Discipline — Situational",trait:"Structure only where the stakes are low",desc:"Perfect systems for trivia and no method at all for anything important.",example:"(colour-coded sock drawer; no filing system for the actual accounts)",intensity:3,rarity:"distinctive",pol:{}},
{id:110186,section:"Personality Traits",category:"Discipline — Situational",trait:"Discipline is entirely borrowed",desc:"Rigorous only while someone else is holding them to it and formless without.",example:"(perfect while she was checking; nothing since she stopped)",intensity:4,rarity:"signature",pol:{}},
{id:110187,section:"Personality Traits",category:"Discipline — Situational",trait:"Sticks to a rule exactly as written",desc:"Total compliance with the letter and complete disregard for the intent.",example:"It says no smoking indoors. It doesn't say anything about the doorway.",intensity:2,rarity:"common",pol:{}},
{id:110188,section:"Personality Traits",category:"Discipline — Situational",trait:"Loses all structure in warm weather",desc:"A reliable seasonal collapse, forecast by everyone who works with them.",example:"(nothing gets done between June and September. It's understood.)",intensity:1,rarity:"common",pol:{}},
{id:110189,section:"Personality Traits",category:"Discipline — Situational",trait:"Rigorous about arrival, indifferent to departure",desc:"Never late to start and entirely unbothered about when anything ends.",example:"(on the dot at nine; still there, aimless, at eight)",intensity:2,rarity:"common",pol:{}},
{id:110190,section:"Personality Traits",category:"Discipline — Situational",trait:"One ritual survives every collapse",desc:"However badly the rest goes, a single practice is never once missed.",example:"(the bed is made. Whatever else has happened, the bed is made.)",intensity:5,rarity:"signature",pol:{}},
{id:110191,section:"Personality Traits",category:"Discipline — Situational",trait:"Plans obsessively, executes improvisationally",desc:"Weeks of preparation abandoned within minutes of contact with the actual day.",example:"(a forty-page plan, and none of it survives ten o'clock)",intensity:3,rarity:"uncommon",pol:{}},
{id:110192,section:"Personality Traits",category:"Discipline — Situational",trait:"Disciplined about money, not about time",desc:"Every penny accounted for and whole afternoons unaccountably gone.",example:"I can tell you where every pound went. No idea about Tuesday.",intensity:2,rarity:"common",pol:{}},
{id:110193,section:"Personality Traits",category:"Discipline — Situational",trait:"Rules apply only to the current project",desc:"Ferocious method inside a piece of work and none between pieces of work.",example:"(three months of order, then six weeks of nothing at all)",intensity:2,rarity:"common",pol:{}},
{id:110194,section:"Personality Traits",category:"Discipline — Situational",trait:"Cleans compulsively before starting anything",desc:"Cannot begin until the space is right, and the tidying can consume the day.",example:"I'll start once the desk is clear. (the desk is never clear)",intensity:3,rarity:"distinctive",pol:{}},
{id:110195,section:"Personality Traits",category:"Discipline — Situational",trait:"Keeps promises to the dead, not the living",desc:"Absolutely unbreakable commitments to whoever is no longer there to check.",example:"I told him I would. So I do. Every year.",intensity:4,rarity:"signature",pol:{}},
{id:110196,section:"Personality Traits",category:"Discipline — Situational",trait:"Order is fully restored before any guest",desc:"Lives in chaos and produces a flawless house on ninety minutes' notice.",example:"(you have never once seen how they actually live)",intensity:2,rarity:"common",pol:{}},

/* ---------- Rebelliousness — Situational ---------- */
{id:110197,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Obeys anyone who's done the work",desc:"Instantly compliant with demonstrated competence and immovable against pure rank.",example:"Show me you've carried it and I'll do whatever you say.",intensity:3,rarity:"distinctive",pol:{}},
{id:110198,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Follows rules, breaks conventions",desc:"Never once in breach of anything written and constantly outside what's merely expected.",example:"There's no regulation against it. There's just a feeling. I don't take feelings.",intensity:3,rarity:"distinctive",pol:{}},
{id:110199,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Compliant in public, insubordinate on paper",desc:"Perfect deference in the room and quietly filed objections afterwards.",example:"Yes, of course. (the memo says otherwise, in writing, on the record)",intensity:3,rarity:"distinctive",pol:{}},
{id:110200,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Defiant only about small rules",desc:"Cheerfully ignores signage and dress codes; obeys everything consequential.",example:"(walks on the grass; has never once been late with the tax)",intensity:2,rarity:"common",pol:{}},
{id:110201,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Kept the vocabulary, lost the appetite",desc:"Still talks like someone who fights the world and has not actually done so in a very long time.",example:"We used to take the doors off. — And now? — Now I quite like a quiet Sunday.",intensity:2,rarity:"common",pol:{}},
{id:110202,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Complies until asked to explain themselves",desc:"Does what's required without argument and refuses absolutely to justify it.",example:"It's done. Why is not part of the arrangement.",intensity:3,rarity:"distinctive",pol:{}},
{id:110203,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Obedient to institutions, defiant to individuals",desc:"Loyal to the organisation and unmanageable for any particular boss.",example:"I'd die for this place. I'm not doing that because you said so.",intensity:3,rarity:"distinctive",pol:{}},
{id:110204,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Resists any rule introduced without warning",desc:"Accepts anything long-standing and reflexively refuses anything new.",example:"Fine, if it's always been the rule. It hasn't. So, no.",intensity:2,rarity:"common",pol:{}},
{id:110205,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Conforms in dress, dissents in substance",desc:"Perfectly unremarkable in appearance and completely unaligned in what they think.",example:"(the suit is impeccable. The opinions are not.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110206,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Defiance is entirely retrospective",desc:"Complies at the time and objects, at length, once it's safely over.",example:"I should have said something. — You had six weeks. — I know.",intensity:3,rarity:"uncommon",pol:{}},
{id:110207,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Only rebels on behalf of a group",desc:"Individually compliant and immediately mutinous the moment it's collective.",example:"On my own I'd have signed it. With the others, no.",intensity:3,rarity:"distinctive",pol:{}},
{id:110208,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Obeys the letter, sabotages the spirit",desc:"Full technical compliance executed so precisely that the intent is destroyed.",example:"You said everything by the book. It'll take nine months.",intensity:4,rarity:"signature",pol:{}},
{id:110209,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Rule-following collapses when hungry or tired",desc:"Compliance is a resource that runs out at a predictable hour.",example:"(the eighth hour is when the arguing starts)",intensity:1,rarity:"common",pol:{}},
{id:110210,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Deference to one authority, contempt for all others",desc:"A single figure or institution commands total obedience; nothing else does.",example:"If she says it, it's done. Everyone else can queue.",intensity:4,rarity:"signature",pol:{}},
{id:110211,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Argues the rule, then follows it exactly",desc:"Objects loudly and comprehensively and then complies without further comment.",example:"This is idiotic and I'll be doing it correctly from Monday.",intensity:2,rarity:"common",pol:{}},
{id:110212,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Conventional at home, unmanageable abroad",desc:"A model citizen in familiar territory and entirely ungovernable elsewhere.",example:"(church every Sunday; deported from two countries)",intensity:3,rarity:"distinctive",pol:{}},
{id:110213,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Refuses only what's compulsory",desc:"Would happily have done it; will not do it once it's required.",example:"I was going to anyway. Then it went on the list.",intensity:3,rarity:"distinctive",pol:{}},
{id:110214,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Defers to process, resists people",desc:"Will accept any outcome that came through the proper channel, and no other.",example:"If the committee said it, fine. If you said it, prove it went to committee.",intensity:2,rarity:"common",pol:{}},
{id:110215,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Rebels precisely once per employer",desc:"Model conduct punctuated by a single, career-defining refusal.",example:"(eleven quiet years, and then the one meeting everyone remembers)",intensity:4,rarity:"signature",pol:{}},
{id:110216,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Compliant with anything explained",desc:"Instantly obedient given a reason and completely immovable without one.",example:"Tell me why and it's done. 'Because' and we're here all day.",intensity:2,rarity:"common",pol:{}},
{id:110217,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Breaks rules to keep a promise",desc:"Entirely law-abiding except where an obligation to a person cuts across it.",example:"I said I'd get him out. The rest is negotiable.",intensity:4,rarity:"signature",pol:{}},
{id:110218,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Nonconformity has a strict dress code",desc:"Rejects mainstream convention in favour of another, equally rigid one.",example:"(everyone in this room refused to conform, identically)",intensity:2,rarity:"uncommon",pol:{}},
{id:110219,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Obedient while the leader is present",desc:"Full compliance in the room and an entirely different operation once alone.",example:"(the moment the car leaves, the actual plan starts)",intensity:3,rarity:"uncommon",pol:{}},
{id:110220,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Cannot be told, can be asked",desc:"An instruction produces refusal; the identical request produces immediate help.",example:"Don't tell me to. Ask me to. It's not the same and I won't pretend it is.",intensity:3,rarity:"distinctive",pol:{}},
{id:110221,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Defies whoever spoke most recently",desc:"Position is reliably opposite to the last person who stated one.",example:"(would have agreed if you'd waited ten seconds)",intensity:2,rarity:"common",pol:{}},
{id:110222,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Conforms exactly until they've earned standing",desc:"Deliberate, patient compliance held in place until it can be spent.",example:"Four years of yes. Then, once, no — and it stuck.",intensity:5,rarity:"signature",pol:{}},
{id:110223,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Resists change, not authority",desc:"Perfectly obedient and completely immovable about anything being done differently.",example:"Whatever you say. We've always done it this way, though.",intensity:2,rarity:"common",pol:{}},
{id:110224,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Rebellion is purely aesthetic",desc:"Everything about their presentation says defiance; every actual choice is orthodox.",example:"(the jacket is a manifesto. The pension is exemplary.)",intensity:2,rarity:"common",pol:{}},
/* ---------- Emotional Capacity — Situational ---------- */
{id:110225,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Feelings present and proportionate",desc:"Neither performative nor sealed: whatever they feel arrives at roughly the size of the event.",example:"That sounds hard. I'm sorry. What would help?",intensity:2,rarity:"common",pol:{mood:1}},
{id:110226,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open about grief, closed about fear",desc:"Will weep in front of anyone and cannot admit to being frightened.",example:"I miss him every day. — Are you scared? — Don't be ridiculous.",intensity:3,rarity:"distinctive",pol:{}},
{id:110227,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Feels it late",desc:"Nothing registers at the time and all of it arrives two days afterwards.",example:"(fine at the funeral. Not fine on Thursday, in a car park.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110228,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Expressive in one language only",desc:"Feeling is available in the mother tongue and simply absent in the other.",example:"(the words for it don't exist in the language I work in)",intensity:4,rarity:"signature",pol:{}},
{id:110229,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open with anyone except the people it concerns",desc:"Talks freely to strangers and cannot say any of it to the person involved.",example:"(a whole evening with a barman; four words to his brother)",intensity:4,rarity:"signature",pol:{}},
{id:110230,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Feeling arrives only through music",desc:"Emotionally unreachable by conversation and completely undone by a song.",example:"(can't discuss it; sat in the car until the track finished)",intensity:3,rarity:"distinctive",pol:{}},
{id:110231,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Warm in daylight, unreachable at night",desc:"A daily cycle in which the interior opens and closes on schedule.",example:"(different person after eleven, every time)",intensity:2,rarity:"common",pol:{}},
{id:110232,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Expresses everything except anger",desc:"Fluent about sadness, love and fear, and entirely silent about being furious.",example:"I'm not angry. (has not been not-angry for eight months)",intensity:3,rarity:"distinctive",pol:{}},
{id:110233,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open in motion, closed at rest",desc:"Can say difficult things while walking or driving and not while sitting still.",example:"Let's talk in the car. It's easier when I'm not looking at you.",intensity:3,rarity:"distinctive",pol:{}},
{id:110234,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Emotionally available in a crisis only",desc:"Fully present and tender when something is wrong and unreachable when it isn't.",example:"(magnificent at the hospital; nothing at all in an ordinary week)",intensity:4,rarity:"signature",pol:{}},
{id:110235,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Names feelings, doesn't show them",desc:"Complete vocabulary and total accuracy delivered with no visible affect at all.",example:"I'm devastated, obviously. (in the voice of a train announcement)",intensity:3,rarity:"distinctive",pol:{}},
{id:110236,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Expressive about other people's lives",desc:"Deeply, visibly moved by anyone's story but their own.",example:"(weeps at the film; nothing at all about the same thing happening to them)",intensity:3,rarity:"distinctive",pol:{}},
{id:110237,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Feeling appears in the body first",desc:"Shows up as posture, appetite and sleep long before any word for it arrives.",example:"You've not eaten since Tuesday. — Have I not. Huh.",intensity:2,rarity:"common",pol:{}},
{id:110238,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open to one person, sealed to the world",desc:"A single relationship in which everything is available, and nowhere else.",example:"(he is the only person who has ever seen it)",intensity:5,rarity:"signature",pol:{}},
{id:110239,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Emotionally fluent in writing only",desc:"Everything they can't say arrives later, at length, in a letter.",example:"(couldn't get a word out; the letter runs to four pages)",intensity:3,rarity:"uncommon",pol:{}},
{id:110240,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Guarded until physically exhausted",desc:"Defences hold perfectly until the body gives out, then everything comes at once.",example:"(hour nineteen, and suddenly he's telling you all of it)",intensity:3,rarity:"distinctive",pol:{}},
{id:110241,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Shows tenderness only through tasks",desc:"Never says it and expresses all of it as food, repairs and small logistics.",example:"(said nothing. Fixed the boiler. That was the sentence.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110242,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Composed about the large, undone by the small",desc:"Steady through catastrophe and reduced to tears by a kindness or a lost object.",example:"(dry-eyed at the diagnosis; broken by the dog's empty bowl)",intensity:3,rarity:"distinctive",pol:{}},
{id:110243,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Depth is available on request only",desc:"Nothing volunteered, everything answered honestly if actually asked.",example:"You have to ask. I'm not going to offer.",intensity:2,rarity:"common",pol:{}},
{id:110244,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open in groups, private one-to-one",desc:"Comfortable being emotional with cover, and evasive without it.",example:"(says it to the whole table; deflects the moment it's just you)",intensity:3,rarity:"distinctive",pol:{}},
{id:110245,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Feels through argument",desc:"The only reliable route to their interior runs through a disagreement.",example:"(the fight is how we find out what's actually wrong)",intensity:3,rarity:"distinctive",pol:{}},
{id:110246,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Available for grief, absent for joy",desc:"Utterly reliable in disaster and unable to be present for anything good.",example:"(first to the hospital; couldn't manage the wedding)",intensity:4,rarity:"signature",pol:{}},
{id:110247,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Emotion only in retrospect",desc:"Reports feelings accurately about the past and has no access to them live.",example:"I think I was frightened. At the time I don't remember thinking anything.",intensity:3,rarity:"uncommon",pol:{}},
{id:110248,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Cries easily, discusses nothing",desc:"Visibly and frequently moved, and completely unwilling to explain any of it.",example:"(tears, then a change of subject, every time)",intensity:2,rarity:"common",pol:{}},
{id:110249,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open exactly once per relationship",desc:"A single unguarded conversation, after which the door closes again for good.",example:"(one night, years ago. Never referred to since.)",intensity:4,rarity:"signature",pol:{}},
{id:110250,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Feeling scales with how little is at stake",desc:"Passionate about films and football and flat about their own circumstances.",example:"(inconsolable about a fictional dog; shrugs about the divorce)",intensity:3,rarity:"distinctive",pol:{}},
{id:110251,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Warm until touched",desc:"Emotionally open right up to any physical contact, which closes it instantly.",example:"(mid-sentence, someone reaches out, and the conversation is over)",intensity:3,rarity:"distinctive",pol:{}},
{id:110252,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Reveals things only while doing something else",desc:"The important sentence always arrives sideways, in the middle of a task.",example:"— pass the tape — I don't think I want to stay married. — the other tape.",intensity:3,rarity:"distinctive",pol:{}},

/* ---------- Intelligence — Situational ---------- */
{id:110253,section:"Personality Traits",category:"Intelligence — Situational",trait:"Analytical about work, instinctive about people",desc:"Rigorous method in one domain and pure gut read in the other, both reliable.",example:"The numbers I'll check. Him I already know about.",intensity:3,rarity:"distinctive",pol:{}},
{id:110254,section:"Personality Traits",category:"Intelligence — Situational",trait:"Sharp until required to be quick",desc:"Excellent thinking given time and visibly worse under any time pressure.",example:"Give me a night with it. Don't make me answer now.",intensity:3,rarity:"uncommon",pol:{}},
{id:110255,section:"Personality Traits",category:"Intelligence — Situational",trait:"Clever aloud, muddled on paper",desc:"Reasons brilliantly in conversation and cannot organise the same argument in writing.",example:"(unanswerable in the room; the memo makes no sense at all)",intensity:3,rarity:"distinctive",pol:{}},
{id:110256,section:"Personality Traits",category:"Intelligence — Situational",trait:"Understands systems, not instructions",desc:"Grasps how a whole thing works immediately and cannot follow a numbered list.",example:"Don't read me the steps. Show me the machine.",intensity:3,rarity:"distinctive",pol:{}},
{id:110257,section:"Personality Traits",category:"Intelligence — Situational",trait:"Precise about the past, vague about the future",desc:"Total recall of what happened and no ability to model what will.",example:"I can tell you what he said in 1994. Next quarter? No idea.",intensity:2,rarity:"common",pol:{}},
{id:110258,section:"Personality Traits",category:"Intelligence — Situational",trait:"Thinks well only while moving",desc:"Nothing arrives sitting down; the problem solves itself on the third mile.",example:"I'll go for a walk and come back with it.",intensity:2,rarity:"common",pol:{}},
{id:110259,section:"Personality Traits",category:"Intelligence — Situational",trait:"Rigorous with numbers, credulous with stories",desc:"Nothing gets past them in a spreadsheet and everything does in an anecdote.",example:"(caught the accounting error; believed the whole thing about the uncle)",intensity:3,rarity:"distinctive",pol:{}},
{id:110260,section:"Personality Traits",category:"Intelligence — Situational",trait:"Smart in the specialty, lost outside it",desc:"World-class in a narrow band and genuinely helpless one step beyond it.",example:"(a decade in the field; cannot work the ticket machine)",intensity:3,rarity:"uncommon",pol:{}},
{id:110261,section:"Personality Traits",category:"Intelligence — Situational",trait:"Analytical until emotionally involved",desc:"Excellent reasoning that switches off entirely once they have a stake.",example:"(surgical about everyone else's marriage)",intensity:3,rarity:"distinctive",pol:{}},
{id:110262,section:"Personality Traits",category:"Intelligence — Situational",trait:"Learns by doing it wrong first",desc:"Cannot absorb an explanation and never repeats a mistake once made.",example:"Let me break it. Then I'll know.",intensity:2,rarity:"common",pol:{}},
{id:110263,section:"Personality Traits",category:"Intelligence — Situational",trait:"Quick with strangers, slow with the familiar",desc:"Fast and adaptive in new territory and stuck in well-worn grooves at home.",example:"(brilliant on the first day; hasn't had a new idea about this in years)",intensity:3,rarity:"distinctive",pol:{}},
{id:110264,section:"Personality Traits",category:"Intelligence — Situational",trait:"Solves problems, cannot state them",desc:"Arrives at the right answer reliably and cannot explain the route.",example:"It's this one. — Why? — It just is. Look at it.",intensity:3,rarity:"distinctive",pol:{}},
{id:110265,section:"Personality Traits",category:"Intelligence — Situational",trait:"Sharp early, unreachable after four",desc:"An entirely dependable daily curve, known to everyone who works with them.",example:"Bring the hard question before lunch.",intensity:1,rarity:"common",pol:{}},
{id:110266,section:"Personality Traits",category:"Intelligence — Situational",trait:"Excellent judgement about others, terrible about themselves",desc:"Reads every situation accurately except the one they're standing in.",example:"(told everyone else exactly what was coming; walked straight into it)",intensity:4,rarity:"signature",pol:{}},
{id:110267,section:"Personality Traits",category:"Intelligence — Situational",trait:"Understands it fully a week later",desc:"Nods along in the moment and genuinely grasps it days after everyone's moved on.",example:"About Tuesday's thing — I've got it now. Are we still doing it?",intensity:2,rarity:"common",pol:{}},
{id:110268,section:"Personality Traits",category:"Intelligence — Situational",trait:"Intelligent about risk, foolish about people",desc:"Impeccable at assessing odds and consistently wrong about who to trust.",example:"(the model was right. The partner was not.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110269,section:"Personality Traits",category:"Intelligence — Situational",trait:"Only rigorous when it's someone else's claim",desc:"Total scepticism applied outward and none at all to their own reasoning.",example:"Where's your evidence? — And yours? — Mine's obvious.",intensity:3,rarity:"distinctive",pol:{}},
{id:110270,section:"Personality Traits",category:"Intelligence — Situational",trait:"Thinks in one domain's metaphors, always",desc:"Every problem gets converted into the language of the one field they know.",example:"(the marriage is a supply chain. The war is a kitchen.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110271,section:"Personality Traits",category:"Intelligence — Situational",trait:"Best thinking arrives in argument",desc:"Nothing much alone and genuinely original the moment someone disagrees.",example:"I don't know what I think until you tell me I'm wrong.",intensity:3,rarity:"uncommon",pol:{}},
{id:110272,section:"Personality Traits",category:"Intelligence — Situational",trait:"Excellent at the start of a problem, poor at the end",desc:"Frames anything superbly and loses interest before the details are settled.",example:"(the first two weeks are inspired; the last two are missing)",intensity:2,rarity:"common",pol:{}},
{id:110273,section:"Personality Traits",category:"Intelligence — Situational",trait:"Knows exactly one thing extraordinarily well",desc:"Depth so far past everyone else in one place that the rest hardly registers.",example:"(nothing to say all evening; then forty minutes on soil)",intensity:5,rarity:"signature",pol:{}},
{id:110274,section:"Personality Traits",category:"Intelligence — Situational",trait:"Cleverness collapses under observation",desc:"Reasons well in private and audibly worse the moment anyone is assessing it.",example:"(fine in the practice; incoherent in the viva)",intensity:3,rarity:"uncommon",pol:{}},
{id:110275,section:"Personality Traits",category:"Intelligence — Situational",trait:"Reads people accurately, acts on it never",desc:"Sees the whole situation clearly and does nothing differently as a result.",example:"I knew he'd do that. — Then why? — I knew. That's not the same as stopping.",intensity:4,rarity:"signature",pol:{}},
{id:110276,section:"Personality Traits",category:"Intelligence — Situational",trait:"Analytical in a second language",desc:"Sloppier and more emotional in their first tongue, rigorous in the acquired one.",example:"(switches language, and the reasoning tightens visibly)",intensity:3,rarity:"distinctive",pol:{}},
{id:110277,section:"Personality Traits",category:"Intelligence — Situational",trait:"Precise about process, indifferent to conclusions",desc:"Cares enormously how a thing was worked out and hardly at all what it says.",example:"Your method's sound. I haven't read the finding.",intensity:3,rarity:"distinctive",pol:{}},
{id:110278,section:"Personality Traits",category:"Intelligence — Situational",trait:"Understands the joke a beat after the room",desc:"Follows everything, reliably, about one second later than everyone else.",example:"(the delayed laugh, every single time)",intensity:1,rarity:"common",pol:{}},
{id:110279,section:"Personality Traits",category:"Intelligence — Situational",trait:"Brilliant with constraints, useless without",desc:"Produces excellent work inside a tight brief and nothing at all given freedom.",example:"Tell me what I can't do and I'll be fine.",intensity:3,rarity:"distinctive",pol:{}},
{id:110280,section:"Personality Traits",category:"Intelligence — Situational",trait:"Reasons well until someone raises their voice",desc:"Cognition is intact exactly as long as the conversation stays quiet.",example:"(a good argument, right up to the shouting; then nothing)",intensity:2,rarity:"common",pol:{}},
/* ---------- Positivity — Situational ---------- */
{id:110281,section:"Personality Traits",category:"Positivity — Situational",trait:"Light about today, resigned about the decade",desc:"Genuinely pleased with the afternoon and expecting nothing at all from the years.",example:"Beautiful morning. Doesn't change where any of this ends up.",intensity:2,rarity:"common",pol:{}},
{id:110282,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimistic for others, bleak about themselves",desc:"Unshakeable faith in everyone else's prospects and none whatsoever in their own.",example:"You'll be fine. — And you? — Different question.",intensity:3,rarity:"distinctive",pol:{}},
{id:110283,section:"Personality Traits",category:"Positivity — Situational",trait:"Delivers ruin in a bright voice",desc:"The content is uniformly catastrophic and the tone is that of good news.",example:"We are completely done for! Shall I put the kettle on?",intensity:3,rarity:"distinctive",pol:{}},
{id:110284,section:"Personality Traits",category:"Positivity — Situational",trait:"Hopeful in company, hopeless alone",desc:"Buoyant with an audience and flatly without expectation in private.",example:"(the life of the room; then the drive home)",intensity:3,rarity:"uncommon",pol:{}},
{id:110285,section:"Personality Traits",category:"Positivity — Situational",trait:"Positive about work, pessimistic about people",desc:"Believes any problem is solvable and no person will change.",example:"We'll fix the process. He'll still be like that afterwards.",intensity:3,rarity:"distinctive",pol:{}},
{id:110286,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimism lasts until the first real setback",desc:"Genuinely upbeat at the start of everything and permanently converted by one failure.",example:"(never quite the same about it after March)",intensity:2,rarity:"common",pol:{}},
{id:110287,section:"Personality Traits",category:"Positivity — Situational",trait:"Bleak in the morning, hopeful by night",desc:"A daily reversal, reliable enough that everyone knows when to raise things.",example:"Ask him after supper. Never at breakfast.",intensity:2,rarity:"common",pol:{}},
{id:110288,section:"Personality Traits",category:"Positivity — Situational",trait:"Expects the worst, prepares for the best",desc:"Voices catastrophe constantly and plans, in practice, as though it will go well.",example:"It'll be a disaster. (has booked the room for the celebration)",intensity:3,rarity:"distinctive",pol:{}},
{id:110289,section:"Personality Traits",category:"Positivity — Situational",trait:"Hope is reserved for other people's children",desc:"Nothing good expected anywhere except in the next generation, unconditionally.",example:"For us? No. For them — yes. Absolutely yes.",intensity:4,rarity:"signature",pol:{}},
{id:110290,section:"Personality Traits",category:"Positivity — Situational",trait:"Cheerful until asked how they are",desc:"Bright and forward-moving right up to any direct enquiry, which stops it dead.",example:"— fine, fine, all fine. Anyway. What about you.",intensity:2,rarity:"common",pol:{}},
{id:110291,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimistic about anything reversible",desc:"Confident wherever a mistake could be undone and bleak about the permanent.",example:"We can always sell it. — And the surgery? — That's different.",intensity:3,rarity:"distinctive",pol:{}},
{id:110292,section:"Personality Traits",category:"Positivity — Situational",trait:"Positive in proportion to how busy they are",desc:"Contented while fully occupied and steadily bleaker with each idle hour.",example:"(give him something to do or he'll start on the state of the world)",intensity:2,rarity:"common",pol:{}},
{id:110293,section:"Personality Traits",category:"Positivity — Situational",trait:"Same face for good news and bad",desc:"Receives a promotion and a bereavement with precisely the same measured nod.",example:"Right. Well. Thank you for telling me.",intensity:1,rarity:"common",pol:{mood:1}},
{id:110294,section:"Personality Traits",category:"Positivity — Situational",trait:"Pessimism is strictly a superstition",desc:"Expects disaster aloud specifically in the belief that saying it prevents it.",example:"Don't say it'll be fine. You'll ruin it.",intensity:3,rarity:"distinctive",pol:{}},
{id:110295,section:"Personality Traits",category:"Positivity — Situational",trait:"Cheerful about disaster, gloomy about inconvenience",desc:"Rises to genuine catastrophe and is defeated entirely by a delayed train.",example:"(unbothered by the fire; ruined by the queue)",intensity:3,rarity:"distinctive",pol:{}},
{id:110296,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimism arrives with the second attempt",desc:"Bleak about anything untried and confident about everything they've already failed at once.",example:"Now I know what it looks like when it goes wrong. Now I'm hopeful.",intensity:3,rarity:"distinctive",pol:{}},
{id:110297,section:"Personality Traits",category:"Positivity — Situational",trait:"Sunny in public, level in private",desc:"Performs brightness socially without any of the exhaustion of faking a mood.",example:"(the smile is real. It just isn't the whole of them.)",intensity:2,rarity:"common",pol:{}},
{id:110298,section:"Personality Traits",category:"Positivity — Situational",trait:"Hopeful only about things they can touch",desc:"Confident about the garden and the roof; hopeless about anything abstract.",example:"The apple tree will come back. The country won't.",intensity:3,rarity:"distinctive",pol:{}},
{id:110299,section:"Personality Traits",category:"Positivity — Situational",trait:"Positivity depends entirely on the weather",desc:"Outlook tracks the sky closely enough to be forecast a day ahead.",example:"(three grey weeks and he's writing off the decade)",intensity:1,rarity:"common",pol:{}},
{id:110300,section:"Personality Traits",category:"Positivity — Situational",trait:"Bleak in general, warm about specifics",desc:"Believes nothing works and is delighted by every particular instance of anything working.",example:"The whole system's rotten. — Lovely bus though, wasn't it.",intensity:3,rarity:"distinctive",pol:{}},
{id:110301,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimism is entirely for the audience's benefit",desc:"Says the hopeful thing because someone needs it, and does not believe a word.",example:"(said it for her. Went outside afterwards and stood in the dark.)",intensity:4,rarity:"signature",pol:{}},
{id:110302,section:"Personality Traits",category:"Positivity — Situational",trait:"Cheerful about the next thing, never the current one",desc:"Whatever is happening is bad; whatever is coming will be much better.",example:"This job's finished for me. The next one, though —",intensity:2,rarity:"common",pol:{}},
{id:110303,section:"Personality Traits",category:"Positivity — Situational",trait:"Hope survives in one specific area only",desc:"Comprehensively bleak with a single, fiercely defended exception.",example:"(no expectations about anything. Except the boy. Never about the boy.)",intensity:5,rarity:"signature",pol:{}},
{id:110304,section:"Personality Traits",category:"Positivity — Situational",trait:"Positive right up to the moment of commitment",desc:"Enthusiastic about every plan until it requires a signature.",example:"Wonderful idea — (pen appears) — although.",intensity:2,rarity:"common",pol:{}},
{id:110305,section:"Personality Traits",category:"Positivity — Situational",trait:"Gloom is a form of politeness",desc:"Downplays every prospect so nobody else has to manage their disappointment.",example:"Don't get your hopes up. (has already quietly arranged it)",intensity:3,rarity:"distinctive",pol:{}},
{id:110306,section:"Personality Traits",category:"Positivity — Situational",trait:"Cheerful with those worse off, bleak with peers",desc:"Rallies for anyone struggling and lets the bottom drop out among equals.",example:"(a tower of hope on the ward; a wreck in the staff room)",intensity:3,rarity:"distinctive",pol:{}},
{id:110307,section:"Personality Traits",category:"Positivity — Situational",trait:"Expects good outcomes and bad behaviour",desc:"Believes things will work out and that people will be awful along the way.",example:"We'll get there. Everyone will be horrible about it.",intensity:3,rarity:"distinctive",pol:{}},
{id:110308,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimism returns each spring, on schedule",desc:"An annual, entirely predictable cycle of hope and its withdrawal.",example:"(every March, the plans. Every November, the silence.)",intensity:2,rarity:"common",pol:{}},

/* ---------- Activeness — Situational ---------- */
{id:110309,section:"Personality Traits",category:"Activeness — Situational",trait:"Tireless outdoors, immovable indoors",desc:"Endless energy in the open air and none at all under a roof.",example:"(nine hours on the hill; asleep in the chair by eight)",intensity:3,rarity:"distinctive",pol:{}},
{id:110310,section:"Personality Traits",category:"Activeness — Situational",trait:"Active in bursts, then flat for days",desc:"Enormous output in short windows separated by genuine, complete stillness.",example:"(four days of everything, then a week of nothing)",intensity:3,rarity:"uncommon",pol:{}},
{id:110311,section:"Personality Traits",category:"Activeness — Situational",trait:"Energetic for other people's projects",desc:"Immediately mobilised by anyone else's need and inert about their own.",example:"(helped move three flats this year; hasn't unpacked their own)",intensity:3,rarity:"distinctive",pol:{}},
{id:110312,section:"Personality Traits",category:"Activeness — Situational",trait:"Physical energy peaks at night",desc:"Sluggish and reluctant all day and fully awake from ten onward.",example:"(the kitchen gets rebuilt between eleven and two)",intensity:2,rarity:"common",pol:{}},
{id:110313,section:"Personality Traits",category:"Activeness — Situational",trait:"Restless in company, still when alone",desc:"Cannot sit through a conversation and entirely content doing nothing by themselves.",example:"(up four times a meal; motionless for an hour on their own)",intensity:3,rarity:"distinctive",pol:{}},
{id:110314,section:"Personality Traits",category:"Activeness — Situational",trait:"Moves constantly, goes nowhere",desc:"Perpetually busy with small motion and no distance covered by any of it.",example:"(on their feet all day; hasn't left the corridor)",intensity:2,rarity:"common",pol:{}},
{id:110315,section:"Personality Traits",category:"Activeness — Situational",trait:"Energetic only with a companion",desc:"Will walk twenty miles with someone and cannot manage the end of the road alone.",example:"I'll go if you're going. Otherwise I won't.",intensity:3,rarity:"distinctive",pol:{}},
{id:110316,section:"Personality Traits",category:"Activeness — Situational",trait:"Active in winter, dormant in summer",desc:"The reverse of everyone around them, consistently and without explanation.",example:"(comes alive in the cold; disappears from May)",intensity:2,rarity:"common",pol:{}},
{id:110317,section:"Personality Traits",category:"Activeness — Situational",trait:"Vigorous when watched, sedentary otherwise",desc:"Considerable effort in front of an audience and none in private.",example:"(a different pace entirely once the office empties)",intensity:2,rarity:"common",pol:{}},
{id:110318,section:"Personality Traits",category:"Activeness — Situational",trait:"Energy is entirely task-shaped",desc:"Inexhaustible for anything with a defined end and unable to start anything open.",example:"Give me a wall to build. Don't tell me to 'get some exercise'.",intensity:3,rarity:"distinctive",pol:{}},
{id:110319,section:"Personality Traits",category:"Activeness — Situational",trait:"Fast on foot, slow to begin",desc:"Considerable capability preceded by a long and immovable reluctance.",example:"(two hours getting out of the door; then gone all day)",intensity:2,rarity:"common",pol:{}},
{id:110320,section:"Personality Traits",category:"Activeness — Situational",trait:"Only tired at home",desc:"Full of energy everywhere in the world and flattened by their own front door.",example:"(fine until the key turns; then straight into the chair)",intensity:3,rarity:"distinctive",pol:{}},
{id:110321,section:"Personality Traits",category:"Activeness — Situational",trait:"Physical in argument, still in peace",desc:"Paces and gestures the moment there's conflict and sits like furniture otherwise.",example:"(you can hear from downstairs when the disagreement starts)",intensity:2,rarity:"common",pol:{}},
{id:110322,section:"Personality Traits",category:"Activeness — Situational",trait:"Energetic until seated",desc:"Capable of anything while upright and completely finished the moment they sit.",example:"Don't let him sit down. That's the whole evening gone.",intensity:2,rarity:"common",pol:{}},
{id:110323,section:"Personality Traits",category:"Activeness — Situational",trait:"Activity is entirely a response to bad news",desc:"Digs, walks and scrubs in exact proportion to what they're not discussing.",example:"(the garden has never looked better. Nobody mentions why.)",intensity:4,rarity:"signature",pol:{}},
{id:110324,section:"Personality Traits",category:"Activeness — Situational",trait:"Strong for short efforts, useless over distance",desc:"Considerable power available briefly and nothing whatsoever in reserve.",example:"(lifted it alone; couldn't carry it ten yards)",intensity:2,rarity:"common",pol:{}},
{id:110325,section:"Personality Traits",category:"Activeness — Situational",trait:"Moves at one speed regardless of urgency",desc:"Precisely the same pace to a fire as to breakfast, and it never varies.",example:"(the building is burning. He is walking.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110326,section:"Personality Traits",category:"Activeness — Situational",trait:"Active while the weather is bad",desc:"Perversely energised by rain and cold and inert in anything pleasant.",example:"(out in the storm; asleep on the first fine day)",intensity:2,rarity:"uncommon",pol:{}},
{id:110327,section:"Personality Traits",category:"Activeness — Situational",trait:"Energetic on arrival, exhausted by the third day",desc:"Every trip, every project, the same steep and predictable curve.",example:"(day one: everything. Day three: the hotel room.)",intensity:2,rarity:"common",pol:{}},
{id:110328,section:"Personality Traits",category:"Activeness — Situational",trait:"Will walk anywhere, will not exercise",desc:"Covers enormous distance incidentally and refuses anything framed as training.",example:"I don't do exercise. I do walk to Dunstable.",intensity:2,rarity:"common",pol:{}},
{id:110329,section:"Personality Traits",category:"Activeness — Situational",trait:"Whole energy level tracks one relationship",desc:"Vigorous or immobile depending entirely on how things stand with one person.",example:"(you can tell how it's going by whether the shed's open)",intensity:5,rarity:"signature",pol:{}},
{id:110330,section:"Personality Traits",category:"Activeness — Situational",trait:"Hands never idle, feet never used",desc:"Has not crossed the room in hours and has quietly repaired four separate things.",example:"(still in the same chair; the clock works again)",intensity:2,rarity:"common",pol:{}},
{id:110331,section:"Personality Traits",category:"Activeness — Situational",trait:"Only rests when given permission",desc:"Cannot stop of their own accord and stops immediately if told to.",example:"Sit down. — (sits down instantly, visibly relieved)",intensity:3,rarity:"distinctive",pol:{}},
{id:110332,section:"Personality Traits",category:"Activeness — Situational",trait:"Energetic in unfamiliar places",desc:"Explores tirelessly anywhere new and barely moves anywhere known.",example:"(walked a strange city till two; won't cross their own town)",intensity:3,rarity:"distinctive",pol:{}},
{id:110333,section:"Personality Traits",category:"Activeness — Situational",trait:"Sedentary except in an emergency",desc:"Habitually motionless and startlingly capable when something actually happens.",example:"(hadn't moved all evening; over the wall in one go)",intensity:3,rarity:"distinctive",pol:{}},
{id:110334,section:"Personality Traits",category:"Activeness — Situational",trait:"Pace matches whoever they're walking with",desc:"No natural speed of their own; adopts the other person's within a few strides.",example:"(never once been the one setting the rhythm)",intensity:1,rarity:"common",pol:{}},
{id:110335,section:"Personality Traits",category:"Activeness — Situational",trait:"Vigorous about beginnings, absent from endings",desc:"Hurls themselves into the first week of anything and is gone by the last.",example:"(dug the whole foundation; never saw the roof go on)",intensity:3,rarity:"uncommon",pol:{}},
{id:110336,section:"Personality Traits",category:"Activeness — Situational",trait:"Stillness is deliberate, not tiredness",desc:"Chooses not to move, obviously and visibly, rather than lacking the energy.",example:"I could. I'm choosing not to. There's a difference.",intensity:2,rarity:"common",pol:{}},

/* ---------- Curiosity — Situational ---------- */
{id:110337,section:"Personality Traits",category:"Curiosity — Situational",trait:"Endlessly curious about people, incurious about ideas",desc:"Wants every detail of a stranger's life and none of any argument.",example:"Never mind the theory — who is he? What does he do on Sundays?",intensity:3,rarity:"distinctive",pol:{}},
{id:110338,section:"Personality Traits",category:"Curiosity — Situational",trait:"Asks nothing, remembers everything",desc:"Never enquires and retains every fact anyone has ever volunteered.",example:"(asked once, in 2009. Still knows the answer.)",intensity:3,rarity:"distinctive",pol:{}},
{id:110339,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious only about what's broken",desc:"No interest at all in anything working and complete absorption in anything that isn't.",example:"(walked past it for years; took it apart the day it stopped)",intensity:3,rarity:"distinctive",pol:{}},
{id:110340,section:"Personality Traits",category:"Curiosity — Situational",trait:"Investigates the past, ignores the present",desc:"Will spend months on an old question and has no view on current events.",example:"(three years on a 14th-century ledger; hasn't read a paper since)",intensity:3,rarity:"distinctive",pol:{}},
{id:110341,section:"Personality Traits",category:"Curiosity — Situational",trait:"Reads widely, asks nothing",desc:"Enormous private appetite and no visible questions in any conversation.",example:"(silent all evening; has read everything either of them mentioned)",intensity:2,rarity:"common",pol:{}},
{id:110342,section:"Personality Traits",category:"Curiosity — Situational",trait:"New interests in bursts of six weeks",desc:"Total immersion in a subject on a reliable and quite short cycle.",example:"(the bee-keeping equipment is next to the kiln)",intensity:2,rarity:"common",pol:{}},
{id:110343,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious in private, incurious in public",desc:"Researches everything alone and never once asks a question in company.",example:"(looked it up at midnight rather than ask at the table)",intensity:3,rarity:"distinctive",pol:{}},
{id:110344,section:"Personality Traits",category:"Curiosity — Situational",trait:"Only interested in what other people already like",desc:"Curiosity is entirely relational: they pursue whatever someone they care about does.",example:"(learned the whole sport because he loved it)",intensity:3,rarity:"distinctive",pol:{}},
{id:110345,section:"Personality Traits",category:"Curiosity — Situational",trait:"Interested up to the point of expertise",desc:"Absorbed until competent and immediately bored the moment they're actually good.",example:"(four instruments, all played adequately, none since)",intensity:3,rarity:"distinctive",pol:{}},
{id:110346,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious about method, not about outcome",desc:"Wants to know how it was done and doesn't care what it produced.",example:"Never mind whether it worked. How did you actually do it?",intensity:3,rarity:"distinctive",pol:{}},
{id:110347,section:"Personality Traits",category:"Curiosity — Situational",trait:"Asks constantly, listens to half",desc:"A steady stream of questions with attention that arrives and departs mid-answer.",example:"— and then what? — (already looking elsewhere) — sorry, go on.",intensity:2,rarity:"common",pol:{}},
{id:110348,section:"Personality Traits",category:"Curiosity — Situational",trait:"Investigates anything they can't afford",desc:"Deep and detailed knowledge of exactly the things out of reach.",example:"(can specify a boat to the fitting; has never owned one)",intensity:2,rarity:"common",pol:{}},
{id:110349,section:"Personality Traits",category:"Curiosity — Situational",trait:"Incurious until personally affected",desc:"Complete indifference to a subject until it touches them, then total absorption.",example:"(never thought about it once. Now knows more than the consultant.)",intensity:3,rarity:"uncommon",pol:{}},
{id:110350,section:"Personality Traits",category:"Curiosity — Situational",trait:"Asks the awkward question, then drops it",desc:"Goes straight to the thing nobody raised and shows no interest in the answer.",example:"So why did you actually leave? — (answer begins) — Anyway.",intensity:3,rarity:"distinctive",pol:{}},
{id:110351,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curiosity ends at the front door",desc:"Boundless interest in the world and complete lack of it about their own household.",example:"(knows the tide tables; couldn't say what year the boiler went in)",intensity:3,rarity:"distinctive",pol:{}},
{id:110352,section:"Personality Traits",category:"Curiosity — Situational",trait:"Wants the summary, never the detail",desc:"Genuinely interested in what a thing is and never in how it works.",example:"Just tell me what it does. Not the rest.",intensity:2,rarity:"common",pol:{}},
{id:110353,section:"Personality Traits",category:"Curiosity — Situational",trait:"Explores physically, not intellectually",desc:"Will go anywhere and read nothing about it before or after.",example:"(four continents; no maps, no history, no plans)",intensity:2,rarity:"common",pol:{}},
{id:110354,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious about everything except themselves",desc:"Investigates the whole world with rigour and has never once turned it inward.",example:"Fascinating question. About me? No, I don't find that interesting.",intensity:4,rarity:"signature",pol:{}},
{id:110355,section:"Personality Traits",category:"Curiosity — Situational",trait:"Only asks questions they know the answer to",desc:"Enquiry is a teaching device, never an actual gap in their knowledge.",example:"And what happens if you do that? (already knows exactly what happens)",intensity:3,rarity:"distinctive",pol:{}},
{id:110356,section:"Personality Traits",category:"Curiosity — Situational",trait:"Interest survives exactly as long as the money",desc:"Committed to a subject for the duration of its funding and not one week longer.",example:"(three years, then nothing; the grant ended)",intensity:2,rarity:"common",pol:{}},
{id:110357,section:"Personality Traits",category:"Curiosity — Situational",trait:"Follows one question for a whole life",desc:"No general curiosity at all and one enquiry pursued for decades.",example:"(everything else is a distraction from the same question since 1987)",intensity:5,rarity:"signature",pol:{}},
{id:110358,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious only about what's forbidden",desc:"Indifferent to anything freely available and immediately fascinated by the withheld.",example:"(no interest until they were told not to open it)",intensity:3,rarity:"distinctive",pol:{}},
{id:110359,section:"Personality Traits",category:"Curiosity — Situational",trait:"Asks about origins, never about plans",desc:"Wants to know where everything and everyone came from and nothing about the future.",example:"Where's the name from? — And what will you do next? — Doesn't matter.",intensity:2,rarity:"common",pol:{}},
{id:110360,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curiosity switches off under stress",desc:"Wide-ranging interest in ordinary weeks and total tunnel vision in a hard one.",example:"(a hundred questions in March; none at all in the bad autumn)",intensity:2,rarity:"common",pol:{}},
{id:110361,section:"Personality Traits",category:"Curiosity — Situational",trait:"Interested in the exception, bored by the rule",desc:"Ignores anything typical and pursues every anomaly to the ground.",example:"Nine hundred normal ones. Tell me about the odd one.",intensity:3,rarity:"distinctive",pol:{}},
{id:110362,section:"Personality Traits",category:"Curiosity — Situational",trait:"Learns anything with someone teaching, nothing alone",desc:"Highly educable in company and incapable of self-directed study.",example:"Show me and I've got it. Leave me the book and I haven't.",intensity:3,rarity:"uncommon",pol:{}},
{id:110363,section:"Personality Traits",category:"Curiosity — Situational",trait:"Asks one question too many, always",desc:"Reliably takes the enquiry a single step past where it was comfortable.",example:"— and does she know? (the room changes temperature)",intensity:3,rarity:"distinctive",pol:{}},
{id:110364,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious in a foreign country only",desc:"Asks nothing at home and everything abroad, of everyone, constantly.",example:"(hasn't asked his neighbour's name in nine years; interviewed half of Lisbon)",intensity:2,rarity:"uncommon",pol:{}},
];

TRAITS.push(...TRAITS_SITUATIONAL);
